local a={...}; if not textutils.serializeJSON then print("Archive tools requires textutils."); return end; local src=a[1]; local dst=a[2] or "archive.json"; if not src or not fs.exists(src) then print("Usage: archive-tools <file> [archive.json]"); return end; local h=fs.open(src,"r"); local data=h.readAll(); h.close(); local o=fs.open(dst,"w"); o.write(textutils.serializeJSON({source=src,data=data})); o.close(); print("Archived "..src.." -> "..dst)